from pathlib import Path
import json
import subprocess
import sys
import xml.etree.ElementTree as ET
import yaml

sys.path.insert(0, '/Users/ab/.codex/skills/.system/skill-creator/scripts')
from quick_validate import validate_skill

changed = subprocess.check_output(['git', 'diff', '--name-only'], text=True).splitlines()
skills = 0
configs = 0
for filename in changed:
    path = Path(filename)
    if path.name == 'SKILL.md':
        valid, message = validate_skill(path.parent)
        assert valid, f'{path}: {message}'
        skills += 1
        continue
    before = subprocess.check_output(['git', 'show', f'HEAD:{filename}'], text=True)
    after = path.read_text()
    if path.suffix == '.json5':
        def decode(value):
            result = subprocess.run(['vendor/bin/json5'], input=value, text=True, capture_output=True, check=True)
            return json.loads(result.stdout)
        assert decode(before) == decode(after), filename
    elif path.suffix in ('.yaml', '.neon'):
        assert yaml.safe_load(before) == yaml.safe_load(after), filename
    elif path.name.endswith('.xml.dist'):
        def effective_rules(value):
            root = ET.fromstring(value)
            root.remove(root.find('description'))
            for node in root.iter():
                node.text = (node.text or '').strip()
                node.tail = None
            return ET.tostring(root)
        assert effective_rules(before) == effective_rules(after), filename
    else:
        raise AssertionError(f'Unexpected changed file: {filename}')
    configs += 1
print(f'Validated {skills} skill files.')
print(f'Compared {configs} parsed configurations: effective settings unchanged (PHPCS display descriptions shortened).')
